479: export function showToast(message, type = 'ok', detail = '') {
480:   const host = toastHost();
481:   while (host.children.length >= 3) host.firstElementChild.remove();
482:   const el = document.createElement('article');
483:   el.className = `toast ${type}`;
484:   el.innerHTML = `<span class="toast-icon">${type === 'error' ? '!' : type === 'info' ? '·' : '✓'}</span>
485:     <div><strong>${esc(message)}</strong>${detail ? `<small>${esc(detail)}</small>` : ''}</div>`;
486:   host.appendChild(el);
487:   requestAnimationFrame(() => el.classList.add('in'));
488:   setTimeout(() => {
489:     el.classList.remove('in');
490:     setTimeout(() => el.remove(), 280);
491:   }, type === 'error' ? 4200 : 3200);
492:   if (type === 'error') sfx('error');
493: }
