742: async function sendChat(raw) {
743:   if (!state || ui.chatBusy) return;
744:   const text = String(raw || '').trim().slice(0, 280);
745:   const npc = state.npcs.find(n => n.id === ui.chatNpcId);
746:   if (!npc || !text) return;
747:   addChatMessage(state, npc.id, 'player', text);
748:   npc.relation = Math.min(100, npc.relation + 0.5);
749:   const playerCount = npc.messages.filter(m => m.role === 'player').length;
750:   if (text.length > 12 && playerCount % 3 === 0) {
751:     addMemory(npc, `On day ${state.time.day}, you told them: “${text.slice(0, 110)}”`);
752:   }
753:   const mentioned = state.tokens.find(t => new RegExp(`\\b${t.ticker}\\b`, 'i').test(text) || text.toLowerCase().includes(t.name.toLowerCase()));
754:   if (mentioned) addMemory(npc, `You asked about $${mentioned.ticker} on day ${state.time.day}.`);
755:   if (/\bbank|loan|credit\b/i.test(text)) addMemory(npc, `You asked them about banking on day ${state.time.day}.`);
756:   saveState(state);
757:   ui.chatBusy = true;
758:   renderNpc();
759:   try {
760:     const out = await reply(npc, state, text);
761:     addChatMessage(state, npc.id, 'npc', out.text);
762:     npc.relation = Math.min(100, npc.relation + 0.3);
763:     if (out.warning) showToast('Neural link fell back', 'info', out.warning);
764:     sfx('message');
765:   } catch (err) {
766:     addChatMessage(state, npc.id, 'npc', 'Something in the city’s signal dropped. Say that again?');
767:     showToast('Conversation link failed', 'error', err?.message || 'Local core unavailable.');
768:   } finally {
769:     ui.chatBusy = false;
770:     saveState(state);
771:     if (ui.chatNpcId === npc.id) { renderNpc(); scrollChat(); }
772:     renderNavBadges(state);
773:   }
774: }
