260: function drawLayer(ctx, buildings, H, color, palette, W, depth, time, motion) {
261:   const baseAlpha = depth === 0 ? 0.78 : depth === 1 ? 0.92 : 1;
262:   for (const b of buildings) {
263:     const h = b.h + (depth === 2 ? H * 0.02 : 0);
264:     const y = H - h;
265:     ctx.globalAlpha = baseAlpha;
266:     ctx.fillStyle = color;
267:     ctx.fillRect(b.x, y, b.w, h);
268:     if (b.tower) {
269:       ctx.fillRect(b.x + b.w / 2 - 1, y - 16, 2, 16);
270:       ctx.fillStyle = '#ff7f74';
271:       ctx.globalAlpha = 0.55 + (motion ? Math.sin(time / 900 + b.x) * 0.3 : 0);
272:       ctx.beginPath(); ctx.arc(b.x + b.w / 2, y - 18, 1.4, 0, 6.28); ctx.fill();
273:     }
274:     if (depth !== 0) {
275:       const col = palette.window[depth % palette.window.length];
276:       for (const l of b.lights) {
277:         const flick = motion ? 0.55 + Math.sin(time / 1300 + l.phase) * 0.25 : 0.7;
278:         ctx.globalAlpha = l.a * flick * (depth === 2 ? 0.65 : 0.5);
279:         ctx.fillStyle = col;
280:         ctx.fillRect(b.x + l.x, y + l.y, 1.6, 2.3);
