283:     if (b.label && depth === 2) {
284:       ctx.globalAlpha = 0.30;
285:       ctx.fillStyle = '#c9ecd9';
286:       ctx.font = '600 7px "JetBrains Mono", monospace';
287:       const label = ['PULSE', 'TIDE', 'CIVIC', 'STRIP', 'VOID'][Math.floor((b.x / W) * 5) % 5];
288:       ctx.fillText(label, b.x + 4, Math.max(8, y + 10));
