295:   const ctx = canvas.getContext('2d');
296:   const dpr = Math.min(2, window.devicePixelRatio || 1);
297:   const rect = canvas.getBoundingClientRect();
298:   const W = Math.max(2, Math.round(rect.width));
299:   const H = Math.max(2, Math.round(rect.height));
300:   if (canvas.width !== Math.round(W * dpr) || canvas.height !== Math.round(H * dpr)) {
301:     canvas.width = Math.round(W * dpr);
302:     canvas.height = Math.round(H * dpr);
303:     canvas.__city = makeCity(W, H, intro);
304:   }
305:   if (!canvas.__city) canvas.__city = makeCity(W, H, intro);
306:   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
307:   ctx.clearRect(0, 0, W, H);
308:   const hour = state?.time?.hour ?? 6.5;
309:   const p = palette(hour, intro);
310:   const g = ctx.createLinearGradient(0, 0, 0, H);
311:   g.addColorStop(0, p.top); g.addColorStop(0.65, p.bottom); g.addColorStop(1, p.near);
312:   ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
313: 
314:   if (p.star > 0) {
315:     const srng = mulberry32(strHash('stars' + Math.round(W)));
316:     ctx.fillStyle = '#e6fff8';
317:     for (let i = 0; i < 50 * p.star; i++) {
318:       const x = srng() * W, y = srng() * H * 0.55;
319:       ctx.globalAlpha = 0.12 + srng() * 0.6 * (0.7 + Math.sin(time / 1200 + i) * 0.3);
320:       ctx.fillRect(x, y, srng() > 0.85 ? 1.5 : 0.8, srng() > 0.85 ? 1.5 : 0.8);
321:     }
322:     ctx.globalAlpha = 1;
323:   }
324: 
325:   // Sun / moon and atmospheric glow.
326:   const sunX = W * (intro ? 0.74 : 0.79);
327:   const sunY = H * (intro ? 0.26 : 0.22);
328:   const sunR = intro ? Math.min(W, H) * 0.075 : 20;
329:   const glow = ctx.createRadialGradient(sunX, sunY, 0, sunX, sunY, sunR * 6);
330:   glow.addColorStop(0, p.glow); glow.addColorStop(0.42, p.glow.replace(/[\d.]+\)$/, '0.06)')); glow.addColorStop(1, 'rgba(0,0,0,0)');
331:   ctx.fillStyle = glow; ctx.fillRect(0, 0, W, H);
332:   ctx.beginPath(); ctx.arc(sunX, sunY, sunR, 0, 6.28); ctx.fillStyle = p.sun; ctx.globalAlpha = 0.9; ctx.fill(); ctx.globalAlpha = 1;
333: 
334:   // Horizon haze.
335:   const hz = ctx.createLinearGradient(0, H * 0.52, 0, H);
336:   hz.addColorStop(0, 'rgba(0,0,0,0)'); hz.addColorStop(0.58, p.haze); hz.addColorStop(1, 'rgba(0,0,0,0)');
337:   ctx.fillStyle = hz; ctx.fillRect(0, 0, W, H);
338: 
339:   drawLayer(ctx, canvas.__city.far, H, p.far, p, W, 0, time, Boolean(state?.settings?.motion));
340:   drawLayer(ctx, canvas.__city.mid, H, p.mid, p, W, 1, time, Boolean(state?.settings?.motion));
341:   drawLayer(ctx, canvas.__city.near, H, p.near, p, W, 2, time, Boolean(state?.settings?.motion));
342: 
343:   // Signal particles.
344:   if (state?.settings?.motion !== false) {
345:     const rng = mulberry32(strHash('particles' + Math.round(W)));
346:     ctx.globalCompositeOperation = 'lighter';
347:     for (let i = 0; i < (intro ? 34 : 18); i++) {
348:       const baseX = rng() * W;
349:       const baseY = H * 0.25 + rng() * H * 0.62;
350:       const speed = 3 + rng() * 10;
351:       const x = baseX + Math.sin(time / 2400 + i) * 12;
352:       const y = ((baseY - (time / 1000) * speed) % (H * 0.75) + H * 0.75) % (H * 0.75) + H * 0.16;
353:       ctx.globalAlpha = 0.12 + (i % 5) * 0.03;
354:       ctx.fillStyle = i % 3 === 0 ? p.window[1] : p.window[0];
355:       ctx.beginPath(); ctx.arc(x, y, i % 7 === 0 ? 1.7 : 0.8, 0, 6.28); ctx.fill();
356:     }
357:     ctx.globalCompositeOperation = 'source-over';
358:     ctx.globalAlpha = 1;
359:   }
360: 
361:   // Foreground rooftop line and cable.
362:   ctx.strokeStyle = 'rgba(150,255,220,.10)';
363:   ctx.lineWidth = 1;
364:   ctx.beginPath(); ctx.moveTo(0, H * 0.94); ctx.lineTo(W, H * 0.94); ctx.stroke();
365: }
366: 
367: export function startSkyline(canvas, state, { intro = false } = {}) {
368:   if (!canvas) return () => {};
369:   let raf = 0, running = true, last = 0;
370:   const motion = state?.settings?.motion !== false;
371:   function frame(now) {
372:     if (!running) return;
373:     if (!motion) { if (last === 0) { drawSkyline(canvas, state, intro, 0); last = 1; } return; }
374:     if (now - last > 32) { drawSkyline(canvas, state, intro, now); last = now; }
375:     raf = requestAnimationFrame(frame);
376:   }
377:   function onResize() {
378:     canvas.__city = null;
379:     drawSkyline(canvas, state, intro, performance.now());
380:   }
381:   window.addEventListener('resize', onResize);
382:   requestAnimationFrame(frame);
383:   return () => {
384:     running = false;
385:     cancelAnimationFrame(raf);
386:     window.removeEventListener('resize', onResize);
387:   };
388: }
389: 
390: /* ————————————— small fx ————————————— */
391: 
392: export function burst(target, color = '#c8ff4d') {
393:   if (!target) return;
394:   const rect = target.getBoundingClientRect();
395:   const host = document.createElement('div');
396:   host.className = 'burst';
397:   host.style.left = rect.left + rect.width / 2 + 'px';
398:   host.style.top = rect.top + rect.height / 2 + 'px';
399:   for (let i = 0; i < 18; i++) {
400:     const s = document.createElement('i');
401:     const angle = Math.random() * Math.PI * 2;
402:     const dist = 30 + Math.random() * 90;
403:     s.style.setProperty('--x', Math.cos(angle) * dist + 'px');
404:     s.style.setProperty('--y', Math.sin(angle) * dist + 'px');
405:     s.style.background = i % 3 === 0 ? '#ffffff' : color;
406:     s.style.animationDelay = (Math.random() * 90) + 'ms';
407:     host.appendChild(s);
408:   }
409:   document.body.appendChild(host);
410:   setTimeout(() => host.remove(), 1100);
411: }

